import {ENEMIES} from './data/enemies.js';
import {pathPoint} from './levels.js';
export const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
export function spawnEnemy(g,type,progress=0,raised=false){const data=ENEMIES[type];const scale={easy:.8,normal:1,hard:1.2,iron:1.2}[g.difficulty];const hp=data.hp*scale;const e={...data,type,id:g.nextId++,hp,maxHP:hp,progress,...pathPoint(g.path,progress),attack:0,special:3,slow:0,burn:0,curse:0,shield:data.shield||0,raised};g.enemies.push(e);return e;}
export function hit(g,e,amount,kind='physical',source){if(e.hp<=0)return;amount*=1+(e.curse>0?.25:0);amount*=1-(kind==='magic'?e.resist:kind==='true'?0:e.armor);if(e.shield>0){const absorbed=Math.min(e.shield,amount);e.shield-=absorbed;amount-=absorbed;}e.hp-=amount;g.effects.push({type:'text',x:e.x,y:e.y-13,text:Math.round(amount),color:kind==='magic'?'#d5b9ee':'#ede0b6',life:.65});if(e.hp<=0){const reward=e.raised?0:e.bounty+(source==='hunter'?2:0);g.gold+=reward;g.kills++;g.save.heroXP+=e.raised?0:1;g.corpses.push({type:e.type,x:e.x,y:e.y,progress:e.progress,life:14,raised:e.raised});for(let i=0;i<5;i++)g.effects.push({type:'particle',x:e.x,y:e.y,vx:(Math.random()-.5)*35,vy:(Math.random()-.5)*35,life:.5,color:e.color});}}
export function defenders(g){return [g.hero,...g.soldiers].filter(s=>s.hp>0);}
export function updateEnemies(g,dt){for(const e of [...g.enemies]){if(e.hp<=0)continue;e.attack-=dt;e.special-=dt;e.slow=Math.max(0,e.slow-dt);e.curse=Math.max(0,e.curse-dt);if(e.burn>0){e.burn-=dt;hit(g,e,6*dt,'true');}e.tunneling=!!e.burrow&&(g.time%6)<3;const blockers=e.air||e.tunneling?[]:defenders(g).filter(s=>distance(s,e)<12&&!s.blockedBy);const blocker=defenders(g).find(s=>s.blockedBy===e.id)||blockers[0];if(blocker&&!e.air&&!e.tunneling&&distance(blocker,e)<17){blocker.blockedBy=e.id;if(e.attack<=0){blocker.hp-= (e.boss?32:e.type==='ogre'?23:e.type==='husk'?4:10)*(1-(blocker.armor||0));e.attack=1.2;if(blocker.hp<=0){blocker.blockedBy=null;blocker.respawn=blocker===g.hero?15:10;}}}else{e.progress+=e.speed*dt*(e.slow>0?.5:1);Object.assign(e,pathPoint(g.path,e.progress));}if(e.special<=0){e.special=e.boss?5:4;if(e.heal){for(const ally of g.enemies)if(ally!==e&&ally.hp>0&&distance(e,ally)<44){ally.hp=Math.min(ally.maxHP,ally.hp+10);g.effects.push({type:'text',x:ally.x,y:ally.y-12,text:'+10',color:'#9cce85',life:.8});}}if(e.necro){const corpse=g.corpses.find(c=>!c.raised&&distance(c,e)<75);if(corpse){spawnEnemy(g,'husk',corpse.progress,true);g.corpses.splice(g.corpses.indexOf(corpse),1);}}if(e.boss){for(const s of defenders(g))if(distance(e,s)<36){s.hp-=25;if(s.hp<=0){s.respawn=s===g.hero?15:10;s.blockedBy=null;}}g.shake=4;g.effects.push({type:'ring',x:e.x,y:e.y,r:36,color:'#e5a577',life:.6});}}if(e.progress>=g.path.length){e.hp=0;g.lives-=e.lives;g.effects.push({type:'text',x:454,y:52,text:`−${e.lives} ♥`,color:'#ed8773',life:1});if(g.lives<=0){g.lives=0;g.finish(false);}}}g.enemies=g.enemies.filter(e=>e.hp>0);for(const s of defenders(g))if(!g.enemies.some(e=>e.id===s.blockedBy&&!e.tunneling&&!e.air&&distance(e,s)<18))s.blockedBy=null;g.corpses=g.corpses.filter(c=>(c.life-=dt)>0);}
